import sys

def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    g = [[int(v) for v in data[2 + i * c: 2 + (i + 1) * c]] for i in range(r)]
    for i in range(r):
        g[i].sort(reverse=(i % 2 == 1))
    for j in range(c):
        col = sorted((g[i][j] for i in range(r)), reverse=(j % 2 == 1))
        for i in range(r):
            g[i][j] = col[i]
    print('\n'.join(' '.join(map(str, row)) for row in g))

